export function upcomingTime(milliseconds){const minutes=Math.floor(Math.max(0,milliseconds)/60000),hours=Math.floor(minutes/60);return hours>=24?`${Math.floor(hours/24)}d ${hours%24}h`:`${hours}h ${minutes%60}m`;}
export function eventIcon(event){const round=event.name==='Gold Rush'?event.fullName.match(/#(\d+)/)?.[1]:null;if(event.registration)return event.name==='Dune Rush'?'drreg.png':round?`d${round}reg.png`:null;const day=event.day??Number(event.label.match(/D(\d+)$/)?.[1]);const prefixes={'Cozy Farm':'cf','Fishing Contest':'fc','Treasure Hunt':'th','Raft Race':'rr','Zobo Shooter':'zs','Dune Rush':'dr'};if(event.name==='Gold Rush')return round?`gr${round}d${day}.png`:null;return prefixes[event.name]?`${prefixes[event.name]}d${day}.png`:null;}
